def gsl_vector_add(a, b):
    # Load libgslcblas.so globally before libgsl.so to resolve dependencies
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the GSL vector class and its methods
    class GSLVector:
        def __init__(self, data):
            self.data = data

        def get_size(self):
            return len(self.data)

        def get_element(self, idx):
            return self.data[idx]

    # Define the vector_add function and its parameters
    gsl.vector_add.argtypes = [ctypes.POINTER(GSLVector), ctypes.POINTER(GSLVector)]
    gsl.vector_add.restype = ctypes.POINTER(GSLVector)

    # Create the input and output vectors
    a_gsl = GSLVector(a)
    b_gsl = GSLVector(b)

    # Call the vector_add function and return its result
    result_gsl = gsl.vector_add(a_gsl, b_gsl)
    result = [result_gsl.get_element(i) for i in range(result_gsl.get_size())]
