def smash_result(input_dict):
    global gsl
    if not gsl:
        gsl = load_gsl()
    if not gsl:
        raise RuntimeError("Failed to load GSL library")

    # Create a new dictionary for the output
    result = {"val": 0.0, "err": 0.0}

    # Call the C function and retrieve the results
    try:
        gsl.gsl_sf_smash_result(ctypes.c_double(input_dict["val"]), ctypes.c_double(input_dict["err"]), ctypes.pointer(ctypes.c_double(result["val"])), ctypes.pointer(ctypes.c_double(result["err"])))
    except:
        raise RuntimeError("Failed to call C function")

    # Return the results as a JSON object
    return json.dumps({"Candidate_solution": result})

