from ctypes import *

# Define the GSLMatrix class
class GSLMatrix:
    def __init__(self, np_array):
        self.matrix = create_gsl_matrix(np_array)
    def copy_matrix(self, dest, src):
        if not (dest.matrix.size == src.matrix.size and dest.matrix.size == self.matrix.size):
            return 0
        ctypes.memcpy(dest.matrix, self.matrix, self.matrix.size)
        return 1
    def create_gsl_matrix(np_array):
        return np_array.ctypes.data_as(POINTER(GSLMatrix))

