class GSL:
    def __init__(self, n):
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self.gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.workspace = None

    def allocate(self, n):
        if not isinstance(n, int):
            raise ValueError("n must be an integer")
        if n <= 0:
            raise ValueError("n must be positive")
        self.workspace = ctypes.POINTER(ctypes.c_double)()
        self.gsl.gsl_integration_workspace_alloc(ctypes.byref(self.workspace), n)
        if not self.workspace:
            raise RuntimeError("failed to allocate workspace")
        return self.workspace

    def free(self):
        if not self.workspace:
            return
        self.gsl.gsl_integration_workspace_free(self.workspace)
        self.workspace = None

