from typing import List, Dict

class GSLFunction:
    def __init__(self, f: float):
        self.f = f

    def __call__(self, x: float) -> float:
        return self.f(x)

def integrate_qk51(func: GSLFunction, a: float, b: float) -> Dict[str, List[float]]:
    gsl = ctypes.CDLL("libgsl.so")
    qk51 = gsl.gsl_integration_qk51
    qk51.argtypes = [GSLFunction, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    qk51.restype = None

    result = [0.0, 0.0]
    error = [0.0, 0.0]

    qk51(func, a, b, ctypes.byref(result), ctypes.byref(error))

    return {"integral": result[0], "absolute_error": error[0]}

def test_func(x: float) -> float:
    return x * x

