import ctypes

class Permutation:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_int * size)()
        self.index = 0

    def next(self):
        if self.index == self.size:
            return False
        else:
            self.data[self.index] += 1
            while self.data[self.index] > self.size and self.index > 0:
                self.data[self.index - 1] += 1
                self.data[self.index] = 0
                self.index -= 1
            if self.index == 0:
                return False
            else:
                return True

    def print(self):
        for i in range(self.size):
            print(self.data[i], end=" ")
        print()

