def find_minmax_indices(matrix):
    # Load the necessary libraries
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Convert the Python list to a GSLMatrix object
    matrix_obj = GSLMatrix(matrix)

    # Call the gsl_matrix_minmax_index function
    min_idx, max_idx = gsl.gsl_matrix_minmax_index(matrix_obj._ptr)

    # Convert the indices to Python integers
    min_row, min_col = matrix_obj.index(min_idx)
    max_row, max_col = matrix_obj.index(max_idx)

    # Return the minimum and maximum indices as a tuple
    return (min_row, min_col, max_row, max_col)

# Define the GSLMatrix class
class GSLMatrix:
    def __init__(self, matrix):
        self._ptr = ctypes.POINTER(ctypes.c_double)(len(matrix), len(matrix[0]))
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                self._ptr[i, j] = matrix[i][j]

    def index(self, idx):
        return (idx // self.size1(), idx % self.size2())

