import ctypes

class GSLFunction:
    def __init__(self, f):
        self.f = f

    def __call__(self, x, params):
        return self.f(x, *params)

gsl_integration_qags = gsl.gsl_integration_qags

def integrate_function(f, a, b, epsabs, epsrel, limit):
    workspace = ctypes.c_void_p()
    error = ctypes.c_int()
    result = ctypes.c_double()

    gsl_integration_qags(GSLFunction(f), a, b, epsabs, epsrel, limit, workspace, result, error)

    free_workspace(workspace)

    return (result.value, abs(error.value))

def free_workspace(workspace):
    gsl.gsl_integration_qags_free(workspace)

# Example usage:
