    def matrix(self) -> List[List[float]]:
        return self._matrix

def matrix_to_gsl(matrix: List[List[float]]) -> GSLMatrix:
    gsl_matrix = ctypes.POINTER(ctypes.c_double * len(matrix))()
    for i, row in enumerate(matrix):
        for j, elem in enumerate(row):
            gsl_matrix[i][j] = elem
    return GSLMatrix(gsl_matrix)

def gsl_matrix_to_numpy(gsl_matrix: GSLMatrix) -> List[List[float]]:
    matrix = []
    for i in range(gsl_matrix.matrix.shape[0]):
        row = []
        for j in range(gsl_matrix.matrix.shape[1]):
            row.append(gsl_matrix.matrix[i][j])
        matrix.append(row)
    return matrix

def compute_matrix_exponential(matrix: List[List[float]], mode: int) -> GSLMatrix:
    gsl_matrix = matrix_to_gsl(matrix)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_linalg_exponential_ss(gsl_matrix, mode)
    return gsl_matrix_to_numpy(gsl_matrix)

