import ctypes
import numpy as np
from scipy.linalg import matrix_power

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix

    @staticmethod
    def matrix_to_gsl(matrix):
        # Convert a square Python matrix to a GSL matrix
        gsl_matrix = ctypes.POINTER(ctypes.c_double * matrix.shape[0] * matrix.shape[1])()
        for i in range(matrix.shape[0]):
            for j in range(matrix.shape[1]):
                gsl_matrix[i*matrix.shape[1]+j] = ctypes.c_double(matrix[i][j])
        return gsl_matrix

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        # Convert a GSL matrix to a NumPy array
        matrix = np.empty((gsl_matrix.shape[0], gsl_matrix.shape[1]))
        for i in range(matrix.shape[0]):
            for j in range(matrix.shape[1]):
                matrix[i][j] = gsl_matrix[i*matrix.shape[1]+j]
        return matrix

    @staticmethod
    def compute_matrix_exponential(matrix, mode=0):
        # Compute the matrix exponential using the GSL library
        gsl_matrix = GSLMatrix.matrix_to_gsl(matrix)
        if mode == 0:
            gsl_matrix_exp = ctypes.POINTER(ctypes.c_double * matrix.shape[0] * matrix.shape[1])()
            status = gsl.gsl_linalg_exponential_ss(gsl_matrix, ctypes.byref(gsl_matrix_exp))
            if status != 0:
                raise Exception("GSL error")
            return GSLMatrix.gsl_matrix_to_numpy(gsl_matrix_exp)
        else:
            matrix_power(matrix, mode)

