import ctypes

class GSL_Error(Exception):
    pass

def compute_bessel_sequence(nu, mode, v):
    size = len(v)
    output = [0] * size

    try:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        Jnu = gsl.gsl_sf_bessel_sequence_Jnu_e(ctypes.c_double(nu), ctypes.c_int(mode), ctypes.POINTER(ctypes.c_double)(v), size)
        if Jnu < 0:
            raise GSL_Error("GSL error: " + str(-Jnu))

        for i in range(size):
            output[i] = v[i] * Jnu

    except GSL_Error as e:
        print(e)
        return None

    return output

