import math

class PoissonDistribution:
    def __init__(self, mu):
        if mu <= 0:
            raise ValueError("Mu must be positive")
        self.mu = mu

    def poisson_cdf_P(self, k):
        if k < 0:
            return 0
        elif k == 0:
            return math.exp(-self.mu) / math.factorial(k)
        else:
            return (math.exp(-self.mu) * math.pow(self.mu, k)) / math.factorial(k)

    def poisson_cdf_Q(self, k):
        if k < 0:
            return 1
        elif k == 0:
            return 1 - math.exp(-self.mu)
        else:
            return 1 - (math.exp(-self.mu) * math.pow(self.mu, k)) / math.factorial(k)

