        array = (ctypes.c_double * size).from_address(ctype_pointer)
        return list(array)

    def __py_to_ctypes(self, py_list):
        ctype_list = (ctypes.c_double * len(py_list))()
        for i in range(len(py_list)):
            ctype_list[i] = py_list[i]
        return ctypes.cast(ctypes.pointer(ctype_list), ctypes.POINTER(ctypes.c_double))

