    except OSError as e:
        raise RuntimeError("Failed to load GSL libraries") from e

    # Compute the Mathieu function Mc using the C function gsl_sf_mathieu_Mc_e
    try:
        result = gsl.gsl_sf_mathieu_Mc_e(kind, order, qq, zz)
        error = gsl.gsl_sf_mathieu_Mc_e_err(result, kind, order, qq, zz)
    except OSError as e:
        raise RuntimeError("Failed to compute Mathieu function Mc") from e

    # Return the result and error as a tuple
    return (result.real, result.imag, error)

